import { Form, useAppForm } from "@/registry/erbium/ui/form";
import { Button } from "@/registry/erbium/ui/button";
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLegend,
  FieldSet,
} from "@/registry/erbium/ui/field";

export const FieldResponsive = () => {
  const form = useAppForm({ defaultValues: { name: "" } });

  return (
    <div className="w-full max-w-lg">
      <Form form={form}>
        <FieldSet>
          <FieldLegend>Profile</FieldLegend>
          <FieldDescription>Fill in your profile information.</FieldDescription>
          <FieldGroup>
            <form.AppField
              name="name"
              validators={{
                onDynamic: ({ value }) => (value.trim() ? undefined : "Enter your name."),
              }}
            >
              {(field) => (
                <field.TextField
                  orientation="responsive"
                  label="Name"
                  placeholder="Alex Smith"
                  autoComplete="name"
                  required
                />
              )}
            </form.AppField>
            <Field orientation="responsive">
              <form.SubmitButton>Submit</form.SubmitButton>
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  form.reset();
                }}
              >
                Reset
              </Button>
            </Field>
          </FieldGroup>
        </FieldSet>
      </Form>
    </div>
  );
};

import { FieldResponsive } from "../examples/field-profile-form";

const Example = () => <FieldResponsive />;

export default Example;
